'use strict';
(()=>{
 const section=document.getElementById('presenterStage'),video=document.getElementById('presenterVideo'),speaker=new Audio(),clock=new PresenterSchedule();
 let settings={},isScreen=false,busy=false,enabled=false,voiceEnabled=false,current='',generation=0,clipsPromise,lastTick=Date.now(),retryAt=0,quietUntil=0,activated=false,watchdog,motionStarted=0,motionHeld=false;
 video.muted=true;video.loop=true;video.playsInline=true;speaker.preload='auto';
 function clips(){return clipsPromise??=fetch('/audio/host-lines.json?v=1').then(r=>{if(!r.ok)throw Error('host-audio');return r.json()}).catch(e=>{clipsPromise=null;throw e})}
 function stop(){clearTimeout(watchdog);generation++;speaker.pause();speaker.currentTime=0;busy=false;current=''}
 function active(){return isScreen&&enabled&&voiceEnabled&&settings.sound&&settings.running&&!settings.paused}
 function report(status,detail){window.dispatchEvent(new CustomEvent('race-audio-state',{detail:{status,detail,voice:'bright'}}))}
 async function play(key){busy=true;current=key;const token=++generation;try{const pack=await clips();if(token!==generation||!active()){if(token===generation)stop();return}speaker.src=pack.clips[key];speaker.volume=Math.max(0,Math.min(1,(settings.volume??20)/100));await speaker.play();if(token!==generation)return;section.classList.add('host-speaking');activated=true;clearTimeout(watchdog);watchdog=setTimeout(()=>{stop();retryAt=Date.now()+10000},30000);report('playing','English host')}catch(e){if(token!==generation)return;busy=false;current='';retryAt=Date.now()+10000;report(e.name==='NotAllowedError'?'blocked':'error',e.name==='NotAllowedError'?'click-enable-sound':'host-audio-playback')}}
 speaker.onended=()=>{clearTimeout(watchdog);quietUntil=Date.now()+3000;if(current)clock.complete(current);busy=false;current='';section.classList.remove('host-speaking');report('ready','English host')};speaker.onerror=()=>{stop();retryAt=Date.now()+10000;section.classList.remove('host-speaking')};
 function updatePresenterMotion(){if(!enabled||!isScreen||!settings.running||settings.paused){motionHeld=false;video.pause();return}if(!motionStarted)motionStarted=Date.now();const move=(settings.presenterMoveSeconds??10)*1000,still=(settings.presenterStillSeconds??4)*1000;motionHeld=settings.presenterMotionPauses!==false&&!busy&&(Date.now()-motionStarted)%(move+still)>=move;if(motionHeld)video.pause();else if(video.paused)video.play().catch(()=>{})}
 function update(r,screen){settings=r.settings;isScreen=screen;enabled=settings.presenterEnabled!==false;voiceEnabled=settings.presenterVoice!==false;section.hidden=!enabled;section.style.setProperty('--presenter-height','calc((100svh - var(--live-safe-bottom,28svh)) * '+((settings.presenterHeightPercent??33)/100)+')');clock.configure({countryDelaySeconds:settings.hostCountryDelaySeconds??60,heartsDelaySeconds:settings.hostHeartsDelaySeconds??120,cheerIntervalSeconds:settings.hostCheerIntervalSeconds??120});if(enabled&&isScreen){if(!video.src)video.src='https://huggingface.co/datasets/afgtakrun/nations-race-gamer-character/resolve/main/english-host-back-v2-silent.mp4';updatePresenterMotion()}else video.pause();if(!active()){stop();section.classList.remove('host-speaking')}}
 document.addEventListener('pointerdown',()=>{retryAt=0;activated=true});video.addEventListener('loadedmetadata',()=>window.dispatchEvent(new Event('resize')));
 setInterval(()=>{const now=Date.now(),delta=Math.min(1000,now-lastTick);lastTick=now;updatePresenterMotion();if(!active())return;clock.advance(delta);if(busy||window.RaceVoice?.busy||now<retryAt||now<quietUntil)return;const key=clock.next(settings.playMode);if(key)play(key)},250);
 window.RaceHost={update,arrival(){if(active())clock.arrival()},quiet(ms=15000){stop();quietUntil=Date.now()+ms;section.classList.remove('host-speaking')},get busy(){return busy},get enabled(){return enabled&&voiceEnabled},get clock(){return clock},get audio(){return speaker},get activated(){return activated},get motionHeld(){return motionHeld}};
})();
